-- Do not edit by hand; change the mapping or the converter and regenerate.
-- Flow: SQ_RAW_PRODUCTS -> EXP_PRODUCTS -> STG_PRODUCTS

with

sq_raw_products as (
    -- SQ_RAW_PRODUCTS (Source Qualifier): reads RAW_PRODUCTS
    select
        cast(sku as varchar) as sku,
        cast(name as varchar) as name,
        cast(type as varchar) as type,
        cast(price as double) as price,
        cast(description as varchar) as description
    from {{ source('raw', 'raw_products') }}
),

exp_products as (
    -- EXP_PRODUCTS (Expression)
    select
        sku as product_id,
        name as product_name,
        type as product_type,
        (price / 100) as product_price,
        price as product_price_cents,
        description as product_description,
        case when (upper(ltrim(rtrim(type))) = 'JAFFLE') then 1 else 0 end as is_food_item,
        case when (upper(ltrim(rtrim(type))) = 'BEVERAGE') then 1 else 0 end as is_drink_item
    from sq_raw_products
),

final as (
    -- STG_PRODUCTS (Target STG_PRODUCTS): cast to the target column types
    select
        cast(product_id as varchar) as product_id,
        cast(product_name as varchar) as product_name,
        cast(product_type as varchar) as product_type,
        cast(product_price_cents as decimal(15, 0)) as product_price_cents,
        cast(product_price as decimal(12, 2)) as product_price,
        cast(product_description as varchar) as product_description,
        cast(is_food_item as decimal(1, 0)) as is_food_item,
        cast(is_drink_item as decimal(1, 0)) as is_drink_item
    from exp_products
)

select * from final
